command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "07d83fd9c6a1033e6f4bd5935ca1f46063f784f5") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "60cf6565f9e5c2c299a721a559c478360140313e") { throw "work branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout work branch failed" }
git merge --no-edit origin/main
if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "latest main merge conflicted" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed after main merge" }
$head=(git rev-parse HEAD).Trim()
Write-Host ("INTEGRATED_HEAD=" + $head)
git push origin HEAD:refs/heads/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "push integrated branch failed" }
Write-Host "LARGE_FOLDER_NAME_INDEX_POLICY_SYNC_PASS"
